import React from 'react';
import PageContainer from '../components/container/container.js';
import Filler from "../components/filler/filler-small.js";

function Impressum() {
  return (
    <PageContainer>

      <div style={{ display: 'block' }}>

        <h3 style={{ color: '#001d2e', fontSize: '1.2em' }}>
          Hinweis zum Impressum
        </h3>

        <p>
          Diese Webseite wird ausschließlich zu privaten Zwecken betrieben. Es finden keine kommerziellen Aktivitäten, Werbung oder Partnerprogramme statt. Daher ist gemäß § 5 DDG (ehemals TMG) und § 18 MStV kein Impressum erforderlich.
        </p>

        <p>
          Kontakt hier: <a href="mailto: 2urbinator2@gmail.com"> Email</a>
        </p>

        <h3 style={{ color: '#001d2e', fontSize: '1.2em' }}>
          Hinweis zum Datenschutz
        </h3>

        <p>
          Der Schutz Ihrer persönlichen Daten ist uns wichtig. Auf dieser Webseite werden keine personenbezogenen Daten erhoben oder verarbeitet. Es gibt kein Kontaktformular, keine Newsletter-Anmeldung, kein Tracking und keine Einbindung externer Dienste, die Daten erfassen oder weitergeben.
        </p>

        <p>
          Aus diesem Grund ist auf dieser Webseite keine weitergehende Datenschutzerklärung erforderlich.
        </p>



      </div>



    </PageContainer>
  );
}

export default Impressum;
